-- LOCAL TEST ONLY: reconstruct the pre-migration application tables omitted
-- from this repository's history. No production data or secrets are imported.
-- Supabase Auth/Storage are minimal metadata models; network delivery is inert.
create role anon;
create role authenticated;
create role service_role bypassrls;
create schema auth;
create schema storage;
create schema private;
create schema extensions;
create schema net;
grant usage on schema public,auth,storage to anon,authenticated,service_role;
grant usage on schema private to authenticated,service_role;
create table auth.users(id uuid primary key,email text,raw_app_meta_data jsonb default '{}',raw_user_meta_data jsonb default '{}',is_anonymous boolean default false);
create table auth.sessions(id uuid primary key,user_id uuid references auth.users on delete cascade);
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
create function auth.uid() returns uuid language sql stable as $$select nullif(auth.jwt()->>'sub','')::uuid$$;
create function auth.role() returns text language sql stable as $$select auth.jwt()->>'role'$$;
grant all on auth.users,auth.sessions to service_role;
create table storage.buckets(id text primary key,name text not null,public boolean default false,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text references storage.buckets(id),name text,owner uuid,owner_id text,metadata jsonb,created_at timestamptz default now(),updated_at timestamptz default now(),unique(bucket_id,name));
alter table storage.objects enable row level security;
grant all on storage.objects,storage.buckets to service_role;
grant select,insert,update,delete on storage.objects to authenticated;
grant select on storage.objects to anon;
create function storage.foldername(name text) returns text[] language sql immutable as $$select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1]$$;
create function storage.extension(name text) returns text language sql immutable as $$select lower(substring(name from '[.]([^.]+)$'))$$;
create function net.http_post(url text,body jsonb default '{}',params jsonb default '{}',headers jsonb default '{}',timeout_milliseconds integer default 1000) returns bigint language sql as $$select 1::bigint$$;
insert into storage.buckets(id,name) values('community-media','community-media');
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,profile_visibility text not null default 'private',daily_goal_minutes integer not null default 20,onboarding_completed boolean not null default false,interests text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using(user_id=auth.uid());
create policy profiles_insert_own on public.profiles for insert to authenticated with check(user_id=auth.uid());
create policy profiles_update_own on public.profiles for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create table public.community_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,author_name text not null,author_initials text not null,activity_type text not null default 'trace',book_title text not null default '',body text not null,visibility text not null default 'me',photo_path text,created_at timestamptz not null default now());
alter table public.community_posts enable row level security;
create policy community_posts_select_visible on public.community_posts for select to authenticated using(author_id=auth.uid() or visibility='public');
create policy community_posts_insert_own on public.community_posts for insert to authenticated with check(author_id=auth.uid());
create policy community_posts_update_own on public.community_posts for update to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid());
create policy community_posts_delete_own on public.community_posts for delete to authenticated using(author_id=auth.uid());
create table public.community_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.community_posts(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,author_name text not null,body text not null,parent_id uuid references public.community_comments(id) on delete cascade,created_at timestamptz not null default now());
alter table public.community_comments enable row level security;
create policy community_comments_select_visible_post on public.community_comments for select to authenticated using(exists(select 1 from public.community_posts p where p.id=post_id));
create policy community_comments_insert_visible_post on public.community_comments for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.community_posts p where p.id=post_id));
create policy community_comments_update_own on public.community_comments for update to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid());
create policy community_comments_delete_own on public.community_comments for delete to authenticated using(author_id=auth.uid());
create table public.community_encouragements(post_id uuid not null references public.community_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
alter table public.community_encouragements enable row level security;
create policy community_encouragements_select_visible_post on public.community_encouragements for select to authenticated using(exists(select 1 from public.community_posts p where p.id=post_id));
create policy community_encouragements_insert_own on public.community_encouragements for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_posts p where p.id=post_id));
create policy community_encouragements_delete_own on public.community_encouragements for delete to authenticated using(user_id=auth.uid());
create table public.reading_clubs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,description text not null default '',visibility text not null default 'private',access_mode text not null default 'approval',book_title text not null default '',color text not null default '#6f927c',created_at timestamptz not null default now());
alter table public.reading_clubs enable row level security;
create policy reading_clubs_select_visible on public.reading_clubs for select to authenticated using(owner_id=auth.uid() or visibility='public');
create policy reading_clubs_insert_own on public.reading_clubs for insert to authenticated with check(owner_id=auth.uid());
create policy reading_clubs_update_own on public.reading_clubs for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy reading_clubs_delete_own on public.reading_clubs for delete to authenticated using(owner_id=auth.uid());
grant select,insert,update,delete on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on tables to authenticated;
alter default privileges in schema public grant usage,select on sequences to authenticated,service_role;
create policy community_media_select_visible_post on storage.objects for select to authenticated using(bucket_id='community-media' and owner_id=auth.uid()::text);
create policy community_media_insert_own on storage.objects for insert to authenticated with check(bucket_id='community-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy community_media_update_own on storage.objects for update to authenticated using(bucket_id='community-media' and owner_id=auth.uid()::text) with check(bucket_id='community-media' and owner_id=auth.uid()::text);
create policy community_media_delete_own on storage.objects for delete to authenticated using(bucket_id='community-media' and owner_id=auth.uid()::text);
-- Existing checks observed earlier in this task (not inferred store policies).
alter table public.community_comments add constraint community_comments_author_name_check check(char_length(author_name) between 2 and 80),add constraint community_comments_body_check check(char_length(body) between 1 and 500);
alter table public.reading_clubs add constraint reading_clubs_name_check check(char_length(name) between 2 and 80),add constraint reading_clubs_description_check check(char_length(description)<=1200),add constraint reading_clubs_book_title_check check(char_length(book_title)<=240),add constraint reading_clubs_visibility_check check(visibility in ('private','public')),add constraint reading_clubs_access_mode_check check(access_mode in ('approval','open')),add constraint reading_clubs_color_check check(color ~ '^#[0-9A-Fa-f]{6}$');
